# Replicate decomposition for demo1
from collections import Counter
bg=Counter(x for row in d1i for x in row).most_common(1)[0][0]
seen=set(); cs=[]
for r in range(len(d1i)):
 for c in range(len(d1i[0])):
  if d1i[r][c]==bg or (r,c) in seen:continue
  q=[(r,c)];seen.add((r,c));co=[]
  while q:
   y,x=q.pop();co.append((y,x))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     p=y+dy,x+dx
     if (dy or dx) and 0<=p[0]<10 and 0<=p[1]<27 and p not in seen and d1i[p[0]][p[1]]!=bg:
      seen.add(p);q.append(p)
  cs.append(co)
print(bg,sorted([len(c) for c in cs],reverse=True))
print('template',sorted(max(cs,key=len)))
print('anchors', [p for c in cs if c is not max(cs,key=len) for p in c])
